{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/nav-actions.json
    The buttons at the end of a top bar: login, the call to action and the theme button (it only reports the press). No wrapper: they sit in the row of the bar.
    Props (p): login, loginHref, cta, ctaHref, actions, tone, themeLabel. -#}
{%- set v_login = ui_def(p['login'], none) -%}
{%- set v_loginHref = ui_def(p['loginHref'], '#/login') -%}
{%- set v_cta = ui_def(p['cta'], none) -%}
{%- set v_ctaHref = ui_def(p['ctaHref'], none) -%}
{%- set v_actions = ui_def(p['actions'], 'cta') -%}
{%- set v_tone = ui_def(p['tone'], 'default') -%}
{%- set v_themeLabel = ui_def(p['themeLabel'], none) -%}
{%- if ui_t(v_login) %}
  {%- set c_1 -%}
    {{ ui_text(v_login) }}
  {%- endset -%}
  {{ ui_include('ui/button/button.html.j2', {'p': {'Variant': 'ghost', 'Size': 'sm', 'Href': ui_s(v_loginHref), 'Class': ui_s(('text-background hover:bg-background/10' if ui_t(ui_eq(v_tone, 'inverse')) else '')), 'Attrs': ui_attrs(['data-testid', 'nav-login'])}, 'children': c_1}) }}
{%- endif %}
{%- if ui_t(ui_and([ui_eq(v_actions, 'cta'), v_cta])) %}
  {%- set c_2 -%}
    {{ ui_text(v_cta) }}
  {%- endset -%}
  {{ ui_include('ui/button/button.html.j2', {'p': {'Variant': ui_s(('secondary' if ui_t(ui_eq(v_tone, 'inverse')) else 'default')), 'Size': 'sm', 'Href': ui_s(v_ctaHref), 'Attrs': ui_attrs(['data-testid', 'header-cta'])}, 'children': c_2}) }}
{%- endif %}
{%- if ui_t(v_themeLabel) %}
  {%- set c_3 -%}
    {{ ui_text(v_themeLabel) }}
  {%- endset -%}
  {{ ui_include('ui/button/button.html.j2', {'p': {'Variant': 'outline', 'Size': 'sm', 'Attrs': ui_attrs(['data-testid', 'theme-toggle'])}, 'children': c_3}) }}
{%- endif %}
